template<typename ETR_REAL>
struct equation_h_dba_t {
  ETR_REAL operator()( ETR_REAL h, EquationParamsDba<ETR_REAL> params ) const {
     ETR_REAL denom_Kd;
     ETR_REAL h_d;
    etr::current_line() = "tsf: dba.R:15 (equation_h_dba): if (h <= 0.0) {...}";
    if (static_cast<bool>(h <= ETR_REAL(0.0))) {
        etr::current_line() = "tsf: dba.R:16 (equation_h_dba): return(1.797693e+308)";
        return(etr::Evaluate(ETR_REAL(1.797693e+308)));
    };
    etr::current_line() = "tsf: dba.R:18 (equation_h_dba): denom_Kd <- 1.0 + params$Kd * h";
    denom_Kd = ETR_REAL(1.0) + params.Kd * h;
    etr::current_line() = "tsf: dba.R:19 (equation_h_dba): h_d <- (params$Kd * h * params$d0) / denom_Kd";
    h_d = (params.Kd * h * params.d0) / denom_Kd;
    etr::current_line() = "tsf: dba.R:20 (equation_h_dba): return(h + h_d - params$h0)";
    return(etr::Evaluate(h + h_d - params.h0));
  }
};
